do $$declare x jsonb;f uuid;pkg uuid;rev integer;perms jsonb;h jsonb;cursor jsonb;n integer:=0;seen uuid[]:='{}';row jsonb;before text;pending jsonb;grants jsonb;begin
 select t.x into x from correction_test.context t;f:=(x->>'factory')::uuid;pkg:=(x->>'package')::uuid;
 perform correction_test.ok(exists(select 1 from public.permission_packages p join public.permission_package_permissions g on g.package_id=p.id where p.factory_id=f and p.template_key='production_engineer' and g.module='orders' and g.action='approve'),'Production Engineer default provisions approval');
 perform correction_test.ok(not has_table_privilege('authenticated','private.production_correction_requests','SELECT'),'pending storage is not directly readable');
 perform correction_test.ok(not has_table_privilege('authenticated','private.production_correction_requests','INSERT'),'pending storage direct DML denied');
 perform correction_test.ok(not has_function_privilege('authenticated','private.apply_approved_production_correction(uuid,jsonb,uuid)','EXECUTE'),'raw M2 delegate revoked');
 perform correction_test.ok(not has_function_privilege('authenticated','private.correct_production(uuid,uuid,numeric,numeric,text,boolean,uuid,uuid,boolean,numeric,text)','EXECUTE'),'quantity worker stays revoked');
 perform correction_test.ok(not has_function_privilege('anon','public.production_correction_command(uuid,text,jsonb,uuid)','EXECUTE'),'anonymous writes denied');
 perform set_config('request.jwt.claim.sub',x->>'worker',false);
 perform correction_test.fails(format('select public.production_correction_read(%L)',(select id from public.factories where id<>f limit 1)),'42501');
 perform set_config('request.jwt.claim.sub','',false);
 perform correction_test.fails(format('select public.production_correction_read(%L)',f),'42501');
 perform set_config('request.jwt.claim.sub',x->>'owner',false);
 select revision into rev from public.permission_packages where id=pkg;
 select jsonb_agg(jsonb_build_object('module',module,'action',action)) into perms from public.permission_package_permissions where package_id=pkg and not(module='orders' and action='approve');
 perform public.save_permission_package(f,pkg,jsonb_build_object('name','Quality Engineer','name_ar','مهندس الجودة'),perms,rev);
 perform private.seed_permission_packages(f);
 perform set_config('request.jwt.claim.sub',x->>'engineer',false);
 perform correction_test.ok(not private.has_permission(f,'orders','approve'),'package approval revocation is effective and not reseeded');
 perform correction_test.fails(format('select public.production_correction_command(%L,''approve'',%L,%L)',f,jsonb_build_object('id',gen_random_uuid()),gen_random_uuid()),'42501');
 perform set_config('request.jwt.claim.sub',x->>'owner',false);
 select revision into rev from public.permission_packages where id=pkg;
 perform public.save_permission_package(f,pkg,jsonb_build_object('name','Quality Engineer','name_ar','مهندس الجودة'),perms||'[{"module":"orders","action":"approve"}]',rev);
 insert into public.user_permissions(factory_id,user_id,module,action) values(f,(x->>'engineer')::uuid,'orders','approve');
 delete from public.user_permissions where factory_id=f and user_id=(x->>'engineer')::uuid and module='orders' and action='approve';
 perform set_config('request.jwt.claim.sub',x->>'engineer',false);
 perform correction_test.ok(private.has_permission(f,'orders','approve'),'removing direct grant does not deny an assigned package grant');
 perform correction_test.fails(format('select public.production_correction_command(%L,''approve'',%L,%L)',x->>'foreign_factory',jsonb_build_object('id',x->>'foreign_request'),gen_random_uuid()),'42501');
 perform correction_test.fails(format('select public.production_correction_command(%L,''approve'',%L,%L)',f,jsonb_build_object('id',x->>'foreign_request'),gen_random_uuid()),'P0002');
 perform set_config('request.jwt.claim.sub',x->>'worker',false);
 pending:=public.production_correction_command(f,'submit',correction_test.payload(x,(x->>'other_entry')::uuid,5,.4,0),gen_random_uuid());
 perform set_config('request.jwt.claim.sub',x->>'owner',false);
 perform public.set_member_permission_packages(f,(x->>'worker')::uuid,array[pkg],array[]::uuid[]);
 perform set_config('request.jwt.claim.sub',x->>'worker',false);
 h:=public.production_correction_command(f,'approve',jsonb_build_object('id',pending->>'id'),gen_random_uuid());
 perform correction_test.ok(h->>'requested_by'=h->>'reviewed_by' and h->>'status'='APPROVED','newly authorized requester may approve their own pending proposal');
 perform set_config('request.jwt.claim.sub',x->>'owner',false);
 perform public.set_member_permission_packages(f,(x->>'worker')::uuid,array[]::uuid[],array[pkg]);
 perform set_config('request.jwt.claim.sub',x->>'worker',false);
 for n in 1..55 loop perform public.production_correction_command(f,'submit',correction_test.payload(x,(x->>'other_entry')::uuid,5,.4,0)||jsonb_build_object('reason','Independent proposal number '||n),gen_random_uuid());end loop;
 cursor:=null;n:=0;before:=correction_test.operational();
 loop
  h:=public.production_correction_read(f,jsonb_build_object('page_size',20,'status','PENDING')||case when cursor is null then '{}'::jsonb else jsonb_build_object('cursor',cursor) end);
  for row in select * from jsonb_array_elements(h->'rows') loop
   if (row->>'id')::uuid=any(seen) then raise exception 'Duplicate request';end if;seen:=array_append(seen,(row->>'id')::uuid);
   if row->>'requested_by'<>x->>'worker' then raise exception 'Another employee proposal exposed';end if;
  end loop;cursor:=h->'next_cursor';n:=n+1;exit when (h->>'complete')::boolean;
 end loop;
 perform correction_test.ok(n>=3 and cardinality(seen)=(h->>'total')::int,'bounded pending pagination with own-request visibility');
 perform correction_test.ok(correction_test.operational()=before,'queue reads do not post quantities');
 cursor:=public.production_correction_read(f,'{"page_size":1}')->'next_cursor';
 perform public.production_correction_command(f,'submit',correction_test.payload(x,(x->>'other_entry')::uuid,5,.4,0),gen_random_uuid());
 perform correction_test.fails(format('select public.production_correction_read(%L,%L)',f,jsonb_build_object('page_size',1,'cursor',cursor)),'40001');
end$$;
select count(*) as cumulative_policy_assertions from correction_test.checks;
select set_config('correction_test.factory',(select x->>'factory' from correction_test.context),false);
set role anon;
do $$begin
 begin perform public.production_correction_read(current_setting('correction_test.factory')::uuid);raise exception 'Expected denial';exception when insufficient_privilege then null;end;
 begin perform public.production_correction_command(current_setting('correction_test.factory')::uuid,'submit','{}',gen_random_uuid());raise exception 'Expected denial';exception when insufficient_privilege then null;end;
end$$;
reset role;
select correction_test.ok(true,'actual anon read/write execution denied');
set role authenticated;
do $$begin
 begin insert into private.production_correction_requests default values;raise exception 'Expected denial';exception when insufficient_privilege then null;end;
 begin perform private.apply_approved_production_correction(current_setting('correction_test.factory')::uuid,'{}',gen_random_uuid());raise exception 'Expected denial';exception when insufficient_privilege then null;end;
end$$;
reset role;
select correction_test.ok(true,'actual authenticated direct DML and raw delegate denied');
